package cn.zhuatech.recruitai.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class InterviewFairnessService{public Result evaluate(Request r){int score=100;List<String> gaps=new ArrayList<>();if(!r.structuredQuestions()){score-=25;gaps.add("使用岗位统一的结构化问题");}if(!r.interviewersTrained()){score-=20;gaps.add("完成面试官公平招聘培训");}if(r.completedScorecards()<r.requiredScorecards()){score-=25;gaps.add("补齐独立评分卡");}if(r.protectedAttributesUsed()){score-=80;gaps.add("移除受保护属性及其代理变量");}if(!r.diversePanel()){score-=10;gaps.add("优化面试小组多样性");}if(!r.decisionRationaleRecorded()){score-=20;gaps.add("记录录用决策的岗位相关依据");}score=Math.max(0,score);String status=r.protectedAttributesUsed()||score<60?"BLOCK":score<90?"REVIEW":"READY";if(gaps.isEmpty())gaps.add("面试流程具备一致、可解释和可审计条件");return new Result(score,status,gaps);}
 public record Request(@NotNull Boolean structuredQuestions,@NotNull Boolean interviewersTrained,@Min(1) int requiredScorecards,@Min(0) int completedScorecards,@NotNull Boolean protectedAttributesUsed,@NotNull Boolean diversePanel,@NotNull Boolean decisionRationaleRecorded){}public record Result(int fairnessScore,String status,List<String> gaps){} }
